import sys
import math

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    t = int(next(iterator))

    results = []

    for _ in range(t):
        n = int(next(iterator))
        ops = []

        if n == 3:
            ops.append((3, 2))
            ops.append((3, 2))
        else:
            cur = n
            while cur > 1:
                target = math.ceil(cur ** 0.5)
                if target < 2:
                    target = 2
                if target == cur:
                    target = cur // 2
                    if target < 2:
                        target = 2

                ops.append((cur, target))
                cur = math.ceil(cur / target)

            for i in range(1, n):
                if i != n:
                    ops.append((i, n))

        results.append(str(len(ops)))
        for x, y in ops:
            results.append(f"{x} {y}")

    sys.stdout.write("\n".join(results) + "\n")

if __name__ == "__main__":
    solve()
